import { pgTable, uuid, varchar, text, bigint, date, timestamp, index, uniqueIndex, pgEnum, check } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { branches } from "./branches.js";
import { attendants } from "./staff.js";

/**
 * Cash the branch holds that belongs to the company, one row per branch per day.
 * The day is the UTC date the cash was PAID (payments.paid_at), never the order's created date.
 * `outstanding` is generated by the database so it can never drift from its parts, and every page
 * (station, history, admin) reads this one table.
 * Amounts are pesewas.
 */
export const cashLedger = pgTable(
  "cash_ledger",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    legacyConvexId: varchar("legacy_convex_id", { length: 64 }).unique(),
    branchId: uuid("branch_id").notNull().references(() => branches.id, { onDelete: "restrict" }),
    day: date("day", { mode: "string" }).notNull(),
    collected: bigint("collected", { mode: "bigint" }).notNull().default(sql`0`),
    orderCount: bigint("order_count", { mode: "number" }).notNull().default(0),
    sent: bigint("sent", { mode: "bigint" }).notNull().default(sql`0`),
    deducted: bigint("deducted", { mode: "bigint" }).notNull().default(sql`0`),
    creditApplied: bigint("credit_applied", { mode: "bigint" }).notNull().default(sql`0`),
    outstanding: bigint("outstanding", { mode: "bigint" })
      .notNull()
      .generatedAlwaysAs(sql`GREATEST(0, collected - sent - deducted - credit_applied)`),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    uniqueIndex("uq_cash_ledger_branch_day").on(table.branchId, table.day),
    check("chk_cash_ledger_nonneg", sql`collected >= 0 AND sent >= 0 AND deducted >= 0 AND credit_applied >= 0`),
  ]
);

export const cashDeductions = pgTable(
  "cash_deductions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    legacyConvexId: varchar("legacy_convex_id", { length: 64 }).unique(),
    branchId: uuid("branch_id").notNull().references(() => branches.id, { onDelete: "restrict" }),
    attendantId: uuid("attendant_id").references(() => attendants.id, { onDelete: "set null" }),
    amountPesewas: bigint("amount_pesewas", { mode: "bigint" }).notNull(),
    reason: varchar("reason", { length: 500 }).notNull(),
    day: date("day", { mode: "string" }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
  },
  (table) => [
    index("idx_cash_deductions_branch_day").on(table.branchId, table.day),
    check("chk_cash_deduction_positive", sql`amount_pesewas > 0`),
  ]
);

export const reconStatusEnum = pgEnum("recon_status", ["pending", "processing", "completed", "failed"]);

/** One row per MoMo send to the company (one Paystack charge). Created BEFORE the charge, so a dropped network can't lose it. */
export const cashReconTransactions = pgTable(
  "cash_recon_transactions",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    legacyConvexId: varchar("legacy_convex_id", { length: 64 }).unique(),
    branchId: uuid("branch_id").notNull().references(() => branches.id, { onDelete: "restrict" }),
    attendantId: uuid("attendant_id").references(() => attendants.id, { onDelete: "set null" }),
    paystackReference: varchar("paystack_reference", { length: 128 }).notNull().unique(),
    paystackTransactionId: varchar("paystack_transaction_id", { length: 64 }),
    amountSentPesewas: bigint("amount_sent_pesewas", { mode: "bigint" }).notNull(),
    senderMomoNumber: varchar("sender_momo_number", { length: 32 }).notNull(),
    network: varchar("network", { length: 16 }),
    status: reconStatusEnum("status").notNull().default("pending"),
    /** Part of amount_sent that was more than the branch owed when it completed (became credit). */
    excessPesewas: bigint("excess_pesewas", { mode: "bigint" }).notNull().default(sql`0`),
    displayText: text("display_text"),
    notes: varchar("notes", { length: 500 }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    completedAt: timestamp("completed_at", { withTimezone: true }),
  },
  (table) => [
    index("idx_recon_branch_created").on(table.branchId, table.createdAt.desc()),
    check("chk_recon_amount_positive", sql`amount_sent_pesewas > 0`),
  ]
);

/** How a completed send was split across unpaid days (oldest first). */
export const cashReconAllocations = pgTable(
  "cash_recon_allocations",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    transactionId: uuid("transaction_id").notNull().references(() => cashReconTransactions.id, { onDelete: "cascade" }),
    branchId: uuid("branch_id").notNull().references(() => branches.id, { onDelete: "restrict" }),
    day: date("day", { mode: "string" }).notNull(),
    amountPesewas: bigint("amount_pesewas", { mode: "bigint" }).notNull(),
  },
  (table) => [
    index("idx_recon_alloc_tx").on(table.transactionId),
    index("idx_recon_alloc_branch_day").on(table.branchId, table.day),
  ]
);

/** Over-sends kept as credit. `remaining` is drawn down (oldest first) as later cash is collected. */
export const cashCredits = pgTable(
  "cash_credits",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    legacyConvexId: varchar("legacy_convex_id", { length: 64 }).unique(),
    branchId: uuid("branch_id").notNull().references(() => branches.id, { onDelete: "restrict" }),
    day: date("day", { mode: "string" }).notNull(),
    amountPesewas: bigint("amount_pesewas", { mode: "bigint" }).notNull(),
    remainingPesewas: bigint("remaining_pesewas", { mode: "bigint" }).notNull(),
    transactionId: uuid("transaction_id").references(() => cashReconTransactions.id, { onDelete: "restrict" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("idx_cash_credits_branch").on(table.branchId, table.day).where(sql`remaining_pesewas > 0`),
    check("chk_cash_credit_bounds", sql`remaining_pesewas >= 0 AND remaining_pesewas <= amount_pesewas`),
  ]
);
